// incSizeToRoot walks from n up to the root, bumping each ancestor's cached
// subtree size by one after a new leaf was linked below n.
func (m *Float64Int64) incSizeToRoot(n *float64Int64TreeNode) {
	for ; n != nil; n = n.parent {
		n.size++
	}
}

// fixSizeToRoot walks from n up to the root recomputing each node's cached
// subtree size from its children. Used after a delete splice (the rotations
// inside fixAfterDelete already maintain their own sizes).
func (m *Float64Int64) fixSizeToRoot(n *float64Int64TreeNode) {
	for ; n != nil; n = n.parent {
		float64Int64TreeNodeFixSize(n)
	}
}

func (m *Float64Int64) fixAfterInsert(z *float64Int64TreeNode) {
	for z.parent != nil && z.parent.color == float64Int64TreeNodeRed {
		if z.parent == z.parent.parent.left {
			y := z.parent.parent.right
			if y != nil && y.color == float64Int64TreeNodeRed {
				z.parent.color = float64Int64TreeNodeBlack
				y.color = float64Int64TreeNodeBlack
				z.parent.parent.color = float64Int64TreeNodeRed
				z = z.parent.parent
			} else {
				if z == z.parent.right {
					z = z.parent
					m.rotateLeft(z)
				}
				z.parent.color = float64Int64TreeNodeBlack
				z.parent.parent.color = float64Int64TreeNodeRed
				m.rotateRight(z.parent.parent)
			}
		} else {
			y := z.parent.parent.left
			if y != nil && y.color == float64Int64TreeNodeRed {
				z.parent.color = float64Int64TreeNodeBlack
				y.color = float64Int64TreeNodeBlack
				z.parent.parent.color = float64Int64TreeNodeRed
				z = z.parent.parent
			} else {
				if z == z.parent.left {
					z = z.parent
					m.rotateRight(z)
				}
				z.parent.color = float64Int64TreeNodeBlack
				z.parent.parent.color = float64Int64TreeNodeRed
				m.rotateLeft(z.parent.parent)
			}
		}
	}
	m.root.color = float64Int64TreeNodeBlack
}

func (m *Float64Int64) deleteNode(z *float64Int64TreeNode) {
	if z.left != nil && z.right != nil {
		succ := m.minNode(z.right)
		z.key = succ.key
		z.value = succ.value
		z = succ
	}
	// z is now the node physically spliced out. fixSizeFrom is the lowest node
	// whose cached subtree size must be refreshed (the removed node's surviving
	// parent at unlink time); recomputing that path to the root once the structure
	// is final restores the invariant. Rotations inside fixAfterDelete maintain
	// their own sizes and everything below fixSizeFrom is left consistent.
	var fixSizeFrom *float64Int64TreeNode
	var child *float64Int64TreeNode
	if z.left != nil {
		child = z.left
	} else {
		child = z.right
	}
	if child != nil {
		child.parent = z.parent
		if z.parent == nil {
			m.root = child
		} else if z == z.parent.left {
			z.parent.left = child
		} else {
			z.parent.right = child
		}
		fixSizeFrom = child
		if z.color == float64Int64TreeNodeBlack {
			m.fixAfterDelete(child)
		}
	} else if z.parent == nil {
		m.root = nil
	} else {
		if z.color == float64Int64TreeNodeBlack {
			m.fixAfterDelete(z)
		}
		// fixAfterDelete may have rotated z to a new parent; read it now.
		fixSizeFrom = z.parent
		if z.parent != nil {
			if z == z.parent.left {
				z.parent.left = nil
			} else {
				z.parent.right = nil
			}
		}
	}
	m.fixSizeToRoot(fixSizeFrom)
}

// --- Data pump (bulk import) ---

// NewFloat64Int64FromSorted builds a Float64Int64 from presorted, ascending keys
// in a single O(n) pass, skipping the per-insert rebalancing of Put. keys must
// be in ascending order according to the map's own comparator (the IEEE-754
// total order for float keys); keys[i] and values[i] form one entry, so the two
// slices must have equal length (a length mismatch is a programmer error and
// panics).
//
// On an out-of-order key it returns pump.ErrNotSorted. On a duplicate key
// it returns pump.ErrDuplicateKey unless policy is
// pump.IgnoreDuplicates, in which case the first value for a key is kept
// and the rest are skipped. A failed build returns a nil map and never a
// half-built one.
//
// The result is observably identical to the same entries inserted one-by-one
// with Put: same iteration order, same lookups. The tree is a valid red-black
// tree, so later Put/Remove preserve the invariant.
func NewFloat64Int64FromSorted(keys []float64, values []int64, policy pump.DuplicatePolicy) (*Float64Int64, error) {
	if len(keys) != len(values) {
		panic("mapdb: NewFloat64Int64FromSorted: len(keys) != len(values)")
	}
	dk, dv, err := dedupFloat64Int64Sorted(keys, values, policy)
	if err != nil {
		return nil, err
	}
	m := NewFloat64Int64()
	m.root = m.buildfloat64Int64(dk, dv, 0, len(dk)-1, 0, pump.RedBlackRedLevel(len(dk)), nil)
	m.size = len(dk)
	return m, nil
}

// dedupFloat64Int64Sorted validates ascending order and applies the duplicate
// policy, returning compacted key/value slices. Equal adjacent keys are the only
// duplicates possible in sorted input.
func dedupFloat64Int64Sorted(keys []float64, values []int64, policy pump.DuplicatePolicy) ([]float64, []int64, error) {
	if len(keys) == 0 {
		return keys, values, nil
	}
	outK := make([]float64, 0, len(keys))
	outV := make([]int64, 0, len(keys))
	outK = append(outK, keys[0])
	outV = append(outV, values[0])
	for i := 1; i < len(keys); i++ {
		cmp := cmpFloat64(keys[i], keys[i-1])
		if cmp < 0 {
			return nil, nil, pump.ErrNotSorted
		}
		if cmp == 0 {
			if policy == pump.IgnoreDuplicates {
				continue
			}
			return nil, nil, pump.ErrDuplicateKey
		}
		outK = append(outK, keys[i])
		outV = append(outV, values[i])
	}
	return outK, outV, nil
}

// buildfloat64Int64 recursively builds a perfectly balanced subtree from the
// sorted slices over [lo, hi], colouring nodes on redLevel red and all others
// black (the classic JDK buildFromSorted). parent wires the back-pointers.
func (m *Float64Int64) buildfloat64Int64(keys []float64, values []int64, lo, hi, level, redLevel int, parent *float64Int64TreeNode) *float64Int64TreeNode {
	if lo > hi {
		return nil
	}
	mid := (lo + hi) / 2
	node := &float64Int64TreeNode{key: keys[mid], value: values[mid], parent: parent, color: float64Int64TreeNodeBlack}
	if level == redLevel {
		node.color = float64Int64TreeNodeRed
	}
	node.left = m.buildfloat64Int64(keys, values, lo, mid-1, level+1, redLevel, node)
	node.right = m.buildfloat64Int64(keys, values, mid+1, hi, level+1, redLevel, node)
	// Set the subtree-size augmentation bottom-up so Rank/Select work after a
	// bulk load exactly as they do after one-by-one Put. Children are already
	// built above, so their sizes are final here.
	node.size = 1 + float64Int64TreeNodeSize(node.left) + float64Int64TreeNodeSize(node.right)
	return node
}

// Float64Int64Sink is a streaming builder for a Float64Int64: callers Put
// ascending entries one at a time, then Build the finished map. It is a thin
// wrapper over NewFloat64Int64FromSorted (entries are buffered, then built in one
// pass), so the build logic and contract live in one place. After an error, or
// after Build, the sink is poisoned and further Put/Build calls panic.
type Float64Int64Sink struct {
	keys   []float64
	values []int64
	policy pump.DuplicatePolicy
	done   bool
}

// NewFloat64Int64Sink creates a streaming sink with the given duplicate policy.
func NewFloat64Int64Sink(policy pump.DuplicatePolicy) *Float64Int64Sink {
	return &Float64Int64Sink{policy: policy}
}

// Put appends one entry. Entries must be supplied in ascending key order; order
// and duplicate violations are reported by Build, not here (the buffer-then-build
// shape detects them in one pass). Calling Put after Build panics.
func (s *Float64Int64Sink) Put(key float64, value int64) {
	if s.done {
		panic("mapdb: Put on a finished Float64Int64Sink")
	}
	s.keys = append(s.keys, key)
	s.values = append(s.values, value)
}

// Build finishes the sink and returns the map. The sink is poisoned afterwards
// (a second Build panics). On an order/duplicate error the map is nil and the
// sink is still poisoned.
func (s *Float64Int64Sink) Build() (*Float64Int64, error) {
	if s.done {
		panic("mapdb: Build on a finished Float64Int64Sink")
	}
	s.done = true
	return NewFloat64Int64FromSorted(s.keys, s.values, s.policy)
}

func (m *Float64Int64) fixAfterDelete(x *float64Int64TreeNode) {
	for x != m.root && x.color == float64Int64TreeNodeBlack {
		if x == x.parent.left {
			w := x.parent.right
			if w == nil {
				x = x.parent
				continue
			}
			if w.color == float64Int64TreeNodeRed {
				w.color = float64Int64TreeNodeBlack
				x.parent.color = float64Int64TreeNodeRed
				m.rotateLeft(x.parent)
				w = x.parent.right
			}
			if w == nil {
				x = x.parent
				continue
			}
			leftBlack := w.left == nil || w.left.color == float64Int64TreeNodeBlack
			rightBlack := w.right == nil || w.right.color == float64Int64TreeNodeBlack
			if leftBlack && rightBlack {
				w.color = float64Int64TreeNodeRed
				x = x.parent
			} else {
				if rightBlack {
					if w.left != nil {
						w.left.color = float64Int64TreeNodeBlack
					}
					w.color = float64Int64TreeNodeRed
					m.rotateRight(w)
					w = x.parent.right
				}
				w.color = x.parent.color
				x.parent.color = float64Int64TreeNodeBlack
				if w.right != nil {
					w.right.color = float64Int64TreeNodeBlack
				}
				m.rotateLeft(x.parent)
				x = m.root
			}
		} else {
			w := x.parent.left
			if w == nil {
				x = x.parent
				continue
			}
			if w.color == float64Int64TreeNodeRed {
				w.color = float64Int64TreeNodeBlack
				x.parent.color = float64Int64TreeNodeRed
				m.rotateRight(x.parent)
				w = x.parent.left
			}
			if w == nil {
				x = x.parent
				continue
			}
			leftBlack := w.left == nil || w.left.color == float64Int64TreeNodeBlack
			rightBlack := w.right == nil || w.right.color == float64Int64TreeNodeBlack
			if leftBlack && rightBlack {
				w.color = float64Int64TreeNodeRed
				x = x.parent
			} else {
				if leftBlack {
					if w.right != nil {
						w.right.color = float64Int64TreeNodeBlack
					}
					w.color = float64Int64TreeNodeRed
					m.rotateLeft(w)
					w = x.parent.left
				}
				w.color = x.parent.color
				x.parent.color = float64Int64TreeNodeBlack
				if w.left != nil {
					w.left.color = float64Int64TreeNodeBlack
				}
				m.rotateRight(x.parent)
				x = m.root
			}
		}
	}
	x.color = float64Int64TreeNodeBlack
}
